window.AUTH=window.AUTH||{};window.AUTH["20-5279"]={"d":"20-5279","id":"2021/20-5279","n":"Wooden v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner William Dale Wooden","date":"2021-05-03","url":"https://www.supremecourt.gov/DocketPDF/20/20-5279/177184/20210503180232826_Wooden%20--%20Opening%20Merits%20Brief%20Final.pdf","side":"pet","n":59},{"k":"respondent","label":"Brief of respondent United States","date":"2021-06-28","url":"https://www.supremecourt.gov/DocketPDF/20/20-5279/182728/20210628161359017_20-5279bsUnitedStates.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioner William Dale Wooden","date":"2021-07-28","url":"https://www.supremecourt.gov/DocketPDF/20/20-5279/185120/20210728124417309_Wooden%20--%20Reply%20Brief%20v.2.pdf","side":"pet","n":38}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/595us2r16_d1pf.pdf","tr":true,"items":[{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"op":2,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"18","1":"16, 45"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Currier v. Virginia","cite":"138 S. Ct. 2144","y":2018,"id":"2017/16-1348","sc":1,"sum":"The Court decided that because Michael Currier consented to a severance of the multiple charges against him, his second trial and resulting conviction, following an acquittal at his first trial, did not violate the double jeopardy clause.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Davis v. State","cite":"765 S.E.2d 336","y":2014,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/765/336/","by":{"0":"42"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Drayton v. United States","cite":"476 F. Supp. 3d 298","y":2020,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/476/298/","by":{"0":"15"}},{"t":"case","label":"Florida Dep’t of Rev. v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"sum":"The Court held 7-2 that the plain meaning of the statute indicates that it only applies to confirmed asset sales, not \"pre-confirmation\" sales.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Gonzales v. Duenas-Alvarez","cite":"549 U.S. 183","y":2007,"id":"2006/05-1629","sc":1,"sum":"The Court ruled unanimously that aiding and abetting a theft qualifies as a \"theft offense\" for purposes of the Immigration and Nationality Act. The opinion by Justice Stephen Breyer held that the common law had done away with all distinctions between \"principals\" and \"aiders and abettors\" of theft crimes.","sumSrc":"Oyez","by":{"0":"40, 41"}},{"t":"case","label":"Green v. State","cite":"213 S.E.2d 60","y":1975,"court":"Ga. App.","url":"https://www.courtlistener.com/c/S.E.2d/213/60/","by":{"0":"28, 40"}},{"t":"case","label":"Griffin v. State","cite":"464 S.E.2d 371","y":1995,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/464/371/","by":{"0":"28"}},{"t":"case","label":"Harris v. United States","cite":"536 U.S. 545","y":2002,"id":"2001/00-10666","sc":1,"sum":"The Court held that section 924(c)(1)(A) defines a single offense, in which brandishing a firearm is a sentencing factor to be found by the judge, not an offense element to be found by the jury.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"op":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"0":"38","1":"30"}},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"sum":"The Court held that Baroni and Kelly, who executed the New Jersey “Bridgegate” political retribution scheme against Fort Lee’s mayor, did not violate the federal-program fraud or wire fraud laws because they did not aim to obtain money or property from the federal Port Authority.","sumSrc":"Oyez","by":{"0":"16","1":"31","2":"7"}},{"t":"case","label":"Loretto v. Teleprompter Manhattan CATV Corp.","cite":"458 U.S. 419","y":1982,"id":"1981/81-244","sc":1,"sum":"The New York statute works a taking of a portion of appellant's property for which she is entitled to just compensation under the Fifth Amendment, as made applicable to the States by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"(IV) Cases—Continued Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/2243/","sc":1,"by":{"0":"38, 42, 43"}},{"t":"case","label":"McCulloch v. State","cite":"849 S.E.2d 795","y":2020,"court":"Ga. App.","url":"https://www.courtlistener.com/c/S.E.2d/849/795/","by":{"0":"40"}},{"t":"case","label":"Miranda v. Arizona","cite":"384 U.S. 436","y":1966,"id":"1965/759","sc":1,"op":1,"sum":"The Court held that law enforcement cannot use testimony given by anyone under interrogation while in custody without that person being informed of their legal rights.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Morgan v. State","cite":"469 S.E.2d 340","y":1996,"court":"Ga. App.","url":"https://www.courtlistener.com/c/S.E.2d/469/340/","op":1,"sum":"Holding that, under § 16–1–7(b), similar drug offenses had to be charged together because they occurred “very close in time” as “part of an ongoing chain of events”.","sumSrc":"opinion","by":{"0":"28"}},{"t":"case","label":"Petty v. United States","cite":"481 U.S. 1034","y":1987,"url":"https://supreme.justia.com/cases/federal/us/481/1034/","sc":1,"op":1,"by":{"0":"11, 24, 34","1":"23","2":"10, 11, 13"}},{"t":"case","label":"Petty v. United States","cite":"828 F.2d 2","y":1987,"url":"https://www.courtlistener.com/c/F.2d/828/2/","op":1,"by":{"0":"24"}},{"t":"case","label":"Rezin v. State","cite":"596 P.2d 226","y":1979,"court":"Nev.","url":"https://www.courtlistener.com/c/P.2d/596/226/","sum":"Rejecting enhancement based on separate treatment for rape and robbery.","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"State v. Riggs","cite":"799 S.E.2d 770","y":2017,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/799/770/","by":{"0":"36"}},{"t":"case","label":"State v. Tavares","cite":"630 P.2d 633","y":1981,"court":"Haw.","url":"https://www.courtlistener.com/c/P.2d/630/633/","ar":1,"sum":"Rejecting enhancement based on separate treatment for two “burglaries which the appellant had committed on December 30, 1974”.","sumSrc":"brief:0","by":{"0":"35","2":"12"}},{"t":"case","label":"Turner v. Arkansas","cite":"407 U.S. 366","y":1972,"id":"1971/71-1309","sc":1,"op":1,"sum":"It must be concluded that the jury (which had been given a charge on accessories) found that petitioner was not present at the robbery-murder scene, thus negating the possibility of a constitutionally valid conviction for the robbery. Ashe v. Swenson, 397 U. S. 436. Petition for certiorari granted; 251 Ark. 499, 473 S. W. 2d 904, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","1":"31"}},{"t":"case","label":"United States v. Barbour","cite":"750 F.3d 535","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/750/535/","ar":1,"by":{"0":"39, 41","2":"15"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"op":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"United States v. Bordeaux","cite":"886 F.3d 189","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/886/189/","op":1,"ar":1,"by":{"0":"12, 30","1":"42","2":"20"}},{"t":"case","label":"United States v. Brady","cite":"988 F.2d 664","y":1993,"url":"https://www.courtlistener.com/c/F.2d/988/664/","by":{"0":"34, 35","1":"43"}},{"t":"case","label":"United States v. Bryant","cite":"136 S. Ct. 1954","y":2016,"id":"2015/15-420","sc":1,"sum":"The Court determined that the use of an uncounseled conviction in tribal court proceedings that complied with the Indian Civil Rights Act of 1968 (ICRA) as a predicate offense under 18 U.S.C. 117(a) did not violate the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"16","1":"30"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"case","label":"United States v. Godinez","cite":"998 F.2d 471","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/998/471/","sum":"Explaining that kidnapping and robbery using victim’s car occurred on separate occasions because, inter alia, the defendant “could have * * * desisted from the planned robbery ”.","sumSrc":"brief:1","by":{"0":"44","1":"29, 36, 39, 40, 45"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"op":1,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"United States v. Hudspeth","cite":"42 F.3d 1015","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/42/1015/","by":{"0":"35, 38","1":"18, 20"}},{"t":"case","label":"United States v. Humphrey","cite":"759 F.3d 909","y":2014,"url":"https://www.courtlistener.com/c/F.3d/759/909/","by":{"0":"43"}},{"t":"case","label":"United States v. Longoria","cite":"874 F.3d 1278","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/1278/","by":{"0":"44"}},{"t":"case","label":"United States v. McCloud","cite":"818 F.3d 591","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/818/591/","by":{"0":"35"}},{"t":"case","label":"United States v. Melbie","cite":"751 F.3d 586","y":2014,"url":"https://www.courtlistener.com/c/F.3d/751/586/","by":{"0":"43"}},{"t":"case","label":"United States v. Murphy","cite":"107 F.3d 1199","y":1997,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/107/1199/","by":{"0":"41","1":"41","2":"15, 16"}},{"t":"case","label":"United States v. Petty","cite":"798 F.2d 1157","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/798/1157/","op":2,"by":{"0":"9, 22","1":"10, 17, 22, 23, 25"}},{"t":"case","label":"United States v. Pham","cite":"872 F.3d 799","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/872/799/","sum":"Rejecting argument that conspiracy conviction “subsumed” discrete convictions for “possession-with-intent-to-distribute offenses from th[e] same year, which [the defendant] committed to further the conspiracy”.","sumSrc":"brief:1","by":{"0":"44","1":"40"}},{"t":"case","label":"United States v. Richardson","cite":"167 F.3d 621","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/167/621/","by":{"0":"36"}},{"t":"case","label":"United States v. Rodriguez-Moreno","cite":"526 U.S. 275","y":1999,"id":"1998/97-1139","sc":1,"sum":"The Court held that \"[v]enue in a prosecution for using or carrying a firearm 'during and in relation to any crime of violence' in violation of section 924(c)(1) is proper in any district where the crime of violence was committed.\" Justice Thomas wrote for the Court that, \"A kidnapping...does not end until the victim is free.","sumSrc":"Oyez","by":{"0":"38","1":"40"}},{"t":"case","label":"United States v. Torres","cite":"961 F.3d 618","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/961/618/","by":{"0":"44","1":"18"}},{"t":"case","label":"United States v. Tucker","cite":"603 F.3d 260","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/603/260/","ar":1,"by":{"0":"41","1":"41","2":"15"}},{"t":"case","label":"United States v. Willoughby","cite":"653 F.3d 738","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/653/738/","by":{"0":"37"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"op":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"31","2":"8"}},{"t":"usc","label":"17 U.S.C. § 114","url":"https://www.law.cornell.edu/uscode/text/17/114","stext":{"head":"§114. Scope of exclusive rights in sound recordings","paras":[[0,"(a) The exclusive rights of the owner of copyright in a sound recording are limited to the rights specified by clauses (1), (2), (3) and (6) of section 106, and do not include any right of performance under section 106(4)."],[0,"(b) The exclusive right of the owner of copyright in a sound recording under clause (1) of section 106 is limited to the right to duplicate the sound recording in the form of phonorecords or copies that directly or indirectly recapture the actual sounds fixed in the recording. The exclusive right of the owner of copyright in a sound recording under clause (2) of section 106 is limited to the right to prepare a derivative work in which the actual sounds fixed in the sound recording are rearranged, remixed, or otherwise altered in sequence or quality. The exclusive rights of the owner of copyright in a sound recording under clauses (1) and (2) of section 106 do not extend to the making or duplication of another sound recording that consists entirely of an independent fixation of other sounds, even though such sounds imitate or simulate those in the copyrighted sound recording. The exclusive rights of the owner of copyright in a sound recording under clauses (1), (2), and (3) of section 106 do not apply to sound recordings included in educational television and radio programs (as defined in section 397 of title 47) distributed or transmitted by or through public broadcasting entities (as defined by section 118(f)): Provided, That copies or phonorecords of said programs are not commercially distributed by or through public broadcasting entities to the general public."],[0,"(c) This section does not limit or impair the exclusive right to perform publicly, by means of a phonorecord, any of the works specified by section 106(4)."],[0,"(d) Limitations on Exclusive Right.—Notwithstanding the provisions of section 106(6)—"],[1,"(1) Exempt transmissions and retransmissions.—The performance of a sound recording publicly by means of a digital audio transmission, other than as a part of an interactive service, is not an infringement of section 106(6) if the performance is part of—"],[2,"(A) a nonsubscription broadcast transmission;"],[2,"(B) a retransmission of a nonsubscription broadcast transmission: Provided, That, in the case of a retransmission of a radio station's broadcast transmission—"],[3,"(i) the radio station's broadcast transmission is not willfully or repeatedly retransmitted more than a radius of 150 miles from the site of the radio broadcast transmitter, however—"],[4,"(I) the 150 mile limitation under this clause shall not apply when a nonsubscription broadcast transmission by a radio station licensed by the Federal Communications Commission is retransmitted on a nonsubscription basis by a terrestrial broadcast station, terrestrial translator, or terrestrial repeater licensed by the Federal Communications Commission; and"],[4,"(II) in the case of a subscription retransmission of a nonsubscription broadcast retransmission covered by subclause (I), the 150 mile radius shall be measured from the transmitter site of such broadcast retransmitter;"],[3,"(ii) the retransmission is of radio station broadcast transmissions that are—"],[4,"(I) obtained by the retransmitter over the air;"],[4,"(II) not electronically processed by the retransmitter to deliver separate and discrete signals; and"],[4,"(III) retransmitted only within the local communities served by the retransmitter;"],[3,"(iii) the radio station's broadcast transmission was being retransmitted to cable systems (as defined in section 111(f)) by a satellite carrier on January 1, 1995, and that retransmission was being retransmitted by cable systems as a separate and discrete signal, and the satellite carrier obtains the radio station's broadcast transmission in an analog format: Provided, That the broadcast transmission being retransmitted may embody the programming of no more than one radio station; or"],[3,"(iv) the radio station's broadcast transmission is made by a noncommercial educational broadcast station funded on or after January 1, 1995, under section 396(k) of the Communications Act of 1934 (47 U.S.C. 396(k)), consists solely of noncommercial educational and cultural radio programs, and the retransmission, whether or not simultaneous, is a nonsubscription terrestrial broadcast retransmission; or"],[2,"(C) a transmission that comes within any of the following categories—"],[3,"(i) a prior or simultaneous transmission incidental to an exempt transmission, such as a feed received by and then retransmitted by an exempt transmitter: Provided, That such incidental transmissions do not include any subscription transmission directly for reception by members of the public;"],[3,"(ii) a transmission within a business establishment, confined to its premises or the immediately surrounding vicinity;"],[3,"(iii) a retransmission by any retransmitter, including a multichannel video programming distributor as defined in section 602(12) 1 of the Communications Act of 1934 (47 U.S.C. 522(12)), of a transmission by a transmitter licensed to publicly perform the sound recording as a part of that transmission, if the retransmission is simultaneous with the licensed transmission and authorized by the transmitter; or"],[3,"(iv) a transmission to a business establishment for use in the ordinary course of its business: Provided, That the business recipient does not retransmit the transmission outside of its premises or the immediately surrounding vicinity, and that the transmission does not exceed the sound recording performance complement. Nothing in this clause shall limit the scope of the exemption in clause (ii)."],[1,"(2) Statutory licensing of certain transmissions.—The performance of a sound recording publicly by means of a subscription digital audio transmission not exempt under paragraph (1), an eligible nonsubscription transmission, or a transmission not exempt under paragraph (1) that is made by a preexisting satellite digital audio radio service shall be subject to statutory licensing, in accordance with subsection (f) if—"],[2,"(A)(i) the transmission is not part of an interactive service;"],[2,"(ii) except in the case of a transmission to a business establishment, the transmitting entity does not automatically and intentionally cause any device receiving the transmission to switch from one program channel to another; and"],[2,"(iii) except as provided in section 1002(e), the transmission of the sound recording is accompanied, if technically feasible, by the information encoded in that sound recording, if any, by or under the authority of the copyright owner of that sound recording, that identifies the title of the sound recording, the featured recording artist who performs on the sound recording, and related information, including information concerning the underlying musical work and its writer;"],[2,"(B) in the case of a subscription transmission not exempt under paragraph (1) that is made by a preexisting subscription service in the same transmission medium used by such service on July 31, 1998, or in the case of a transmission not exempt under paragraph (1) that is made by a preexisting satellite digital audio radio service—"],[3,"(i) the transmission does not exceed the sound recording performance complement; and"],[3,"(ii) the transmitting entity does not cause to be published by means of an advance program schedule or prior announcement the titles of the specific sound recordings or phonorecords embodying such sound recordings to be transmitted; and"],[2,"(C) in the case of an eligible nonsubscription transmission or a subscription transmission not exempt under paragraph (1) that is made by a new subscription service or by a preexisting subscription service other than in the same transmission medium used by such service on July 31, 1998—"],[3,"(i) the transmission does not exceed the sound recording performance complement, except that this requirement shall not apply in the case of a retransmission of a broadcast transmission if the retransmission is made by a transmitting entity that does not have the right or ability to control the programming of the broadcast station making the broadcast transmission, unless—"],[4,"(I) the broadcast station makes broadcast transmissions—"],[5,"(aa) in digital format that regularly exceed the sound recording performance complement; or"],[5,"(bb) in analog format, a substantial portion of which, on a weekly basis, exceed the sound recording performance complement; and"],[4,"(II) the sound recording copyright owner or its representative has notified the transmitting entity in writing that broadcast transmissions of the copyright owner's sound recordings exceed the sound recording performance complement as provided in this clause;"],[3,"(ii) the transmitting entity does not cause to be published, or induce or facilitate the publication, by means of an advance program schedule or prior announcement, the titles of the specific sound recordings to be transmitted, the phonorecords embodying such sound recordings, or, other than for illustrative purposes, the names of the featured recording artists, except that this clause does not disqualify a transmitting entity that makes a prior announcement that a particular artist will be featured within an unspecified future time period, and in the case of a retransmission of a broadcast transmission by a transmitting entity that does not have the right or ability to control the programming of the broadcast transmission, the requirement of this clause shall not apply to a prior oral announcement by the broadcast station, or to an advance program schedule published, induced, or facilitated by the broadcast station, if the transmitting entity does not have actual knowledge and has not received written notice from the copyright owner or its representative that the broadcast station publishes or induces or facilitates the publication of such advance program schedule, or if such advance program schedule is a schedule of classical music programming published by the broadcast station in the same manner as published by that broadcast station on or before September 30, 1998;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/114?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§114. Scope of exclusive rights in sound recordings","tname":"Copyrights","by":{"0":"32"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"0":"40"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"39","2":"18"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(i)(1)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"head":"§994. Duties of the Commission","tname":"Judiciary and Judicial Procedure","by":{"0":"31","1":"33, 34"}},{"t":"usc","label":"40 U.S.C. § 6136","url":"https://www.law.cornell.edu/uscode/text/40/6136","stext":{"head":"§6136. Suspension of prohibitions against use of Supreme Court grounds","paras":[[0,"To allow the observance of authorized ceremonies in the Supreme Court Building and grounds, the Marshal of the Supreme Court may suspend for those occasions any of the prohibitions contained in this subchapter as may be necessary for the occasion if—"],[1,"(1) responsible officers have been appointed; and"],[1,"(2) the Marshal determines that adequate arrangements have been made—"],[2,"(A) to maintain suitable order and decorum in the proceedings; and"],[2,"(B) to protect the Supreme Court Building and grounds and individuals and property in the Building and grounds."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/40/6136?type=usc&year=mostrecent&link-type=html"},"head":"§6136. Suspension of prohibitions against use of Supreme Court grounds","tname":"Public Buildings, Property, and Works","by":{"0":"15","1":"30"}},{"t":"usc","label":"42 U.S.C. § 4104c","url":"https://www.law.cornell.edu/uscode/text/42/4104c","subs":["(d)(2)"],"by":{"0":"15"}},{"t":"law","label":"Pub. L. No. 100-690","url":"https://www.govinfo.gov/link/statute/102/4402","by":{"0":"24","1":"24"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2185","by":{"0":"21"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"0":"21","1":"21"}},{"t":"law","label":"Pub. L. No. 91-513","url":"https://www.govinfo.gov/link/statute/84/1236","by":{"0":"23","1":"32"}},{"t":"law","label":"Pub. L. No. 91-452","url":"https://www.govinfo.gov/link/statute/84/922","by":{"0":"18"}},{"t":"case","label":"Akassy v. Hardy","cite":"887 F.3d 91","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/887/91/","by":{"1":"15"}},{"t":"case","label":"Ashe v. Swenson","cite":"397 U.S. 436","y":1970,"id":"1969/57","sc":1,"sum":"Three or four men robbed six poker players. Petitioner was separately charged with having robbed one of the players, Knight, who along with three others testified for the prosecution that each had been robbed. The State's evidence that petitioner had been one of the robbers was weak. The defense offered no testimony. The trial judge instructed the jury that if it found that petitioner participated in the robbery, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"(III) Cases—Continued: Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Borden v. United States","cite":"2021 WL 2367312","y":2021,"court":"June 10","sum":"Observing that where “[d]ictionaries offer definitions” of a word “consistent with both parties’ view,” the surrounding words may be decisive.","sumSrc":"brief:1","by":{"1":"27, 30, 35, 45"}},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"sum":"The Court found that the \"failure to report\" crime does not satisfy the Armed Career Criminals Act's (ACCA) \"crime of violence\" definition.","sumSrc":"Oyez","by":{"1":"16","2":"3, 4"}},{"t":"case","label":"Coleman v. Tollefson","cite":"575 U.S. 532","y":2015,"id":"2014/13-1333","sc":1,"sum":"The Court held that a district court’s dismissal of a lawsuit counts as a “strike” for the purpose of the Prison Litigation Reform Act’s “three strikes” provision when the case is pending on appeal.","sumSrc":"Oyez","by":{"1":"passim","2":"2, 8, 9"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"2021 WL 2459253","y":2021,"court":"June 17","by":{"1":"35"}},{"t":"case","label":"General Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Hamling v. United States","cite":"418 U.S. 87","y":1974,"id":"1973/73-507","sc":1,"sum":"Petitioners were convicted of mailing and conspiring to mail an obscene advertising brochure with sexually explicit photographic material relating to their illustrated version (hereafter Illustrated Report) of an official report on obscenity, in violation of 18 U. S. C. §§ 2, 371, and 1461. The indictment under § 1461 charged petitioners in the language of the statute, which provides in pertinent part that obscene …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Intel Corp. Inv. Policy Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Kirkland v. United States","cite":"687 F.3d 878","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/687/878/","by":{"1":"46"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"1":"4, 35","2":"19, 22"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"sum":"Bribery of private employees prohibited by state criminal statutes violates the Travel Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"19, 47"}},{"t":"case","label":"Sandifer v. United States Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"ar":1,"sum":"The Court held that while a guilty plea could qualify as a predicate offense under the ACCA, courts may only look to the following when determining if that plea admitted to generic burglary: the terms of the charging document, the terms of a plea agreement, or a judicial record in which the defendant confirmed the factual basis for the plea (such as conversation between defendant and judge).","sumSrc":"Oyez","by":{"1":"4, 18, 46","2":"17, 19"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"op":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"op":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 16, 19, 21, 36, 46"}},{"t":"case","label":"Toussie v. United States","cite":"397 U.S. 112","y":1970,"id":"1969/441","sc":1,"sum":"The offense is not a continuing one but was committed by petitioner's failure to register in 1959, when the statute of limitations began to run. Pp. 114-124. 410 F. 2d 1156, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 40","2":"6"}},{"t":"case","label":"United States v. Abbott","cite":"794 F.3d 896","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/896/","op":1,"sum":"Recognizing that two cocaine sales to an undercover officer for the same price on consecutive days constituted different occasions.","sumSrc":"brief:1","by":{"1":"19, 43"}},{"t":"case","label":"United States v. Antonie","cite":"953 F.2d 496","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/953/496/","by":{"1":"43","2":"20"}},{"t":"case","label":"United States v. Carnes","cite":"309 F.3d 950","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/950/","by":{"1":"42","2":"14"}},{"t":"case","label":"United States v. Carr","cite":"592 F.3d 636","y":2010,"url":"https://www.courtlistener.com/c/F.3d/592/636/","by":{"1":"20"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. Dantzler","cite":"771 F.3d 137","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/771/137/","by":{"1":"46"}},{"t":"case","label":"United States v. Fuller","cite":"453 F.3d 274","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/453/274/","op":1,"by":{"1":"18, 41","2":"15, 16, 17"}},{"t":"case","label":"United States v. Gundy","cite":"842 F.3d 1156","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/842/1156/","by":{"1":"5"}},{"t":"case","label":"United States v. Johnson","cite":"130 F.3d 1420","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/130/1420/","by":{"1":"19"}},{"t":"case","label":"United States v. Leeson","cite":"453 F.3d 631","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/453/631/","op":1,"sum":"Explaining that “ ‘occasions’ are ‘those predicate offenses that can be isolated with a beginning and an end—ones that constitute an occurrence unto themselves’ ”.","sumSrc":"brief:1","by":{"1":"19"}},{"t":"case","label":"United States v. Letterlough","cite":"63 F.3d 332","y":1995,"url":"https://www.courtlistener.com/c/F.3d/63/332/","op":1,"by":{"1":"44"}},{"t":"case","label":"United States v. Maxey","cite":"989 F.2d 303","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/989/303/","by":{"1":"18"}},{"t":"case","label":"United States v. McElyea","cite":"158 F.3d 1016","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/158/1016/","sum":"Noting that no Senate or House Report was submitted for this amendment.","sumSrc":"brief:1","by":{"1":"24, 37, 41","2":"13"}},{"t":"case","label":"United States v. Phillips","cite":"149 F.3d 1026","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/149/1026/","by":{"1":"20"}},{"t":"case","label":"United States v. Pope","cite":"132 F.3d 684","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/132/684/","sum":"Explaining that “so long as predicate crimes are successive rather than simultaneous, they constitute separate” ACCA predicates.","sumSrc":"brief:1","by":{"1":"18, 19, 43","2":"15"}},{"t":"case","label":"United States v. Shabani","cite":"513 U.S. 10","y":1994,"id":"1994/93-981","sc":1,"sum":"In order to establish a violation of §846, the Government need not prove the commission of any overt acts in furtherance of the conspiracy. The statute's plain language does not require an overt act, and such a requirement has not been inferred from congressional silence in other conspiracy statutes, see, e. g., Nash v. United States, 229 U. S. 373. Thus, absent contrary indications, it is presumed that Congress …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"sum":"The term “burglary” in the Armed Career Criminal Act includes burglary of a structure or vehicle that has been adapted or is customarily used for overnight accommodation.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16, 17, 45","2":"3"}},{"t":"case","label":"United States v. Tisdale","cite":"921 F.2d 1095","y":1990,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/921/1095/","by":{"1":"21, 37"}},{"t":"case","label":"United States v. Towne","cite":"870 F.2d 880","y":1989,"url":"https://www.courtlistener.com/c/F.2d/870/880/","by":{"1":"22"}},{"t":"case","label":"United States v. Weeks","cite":"711 F.3d 1255","y":2013,"url":"https://www.courtlistener.com/c/F.3d/711/1255/","by":{"1":"42"}},{"t":"case","label":"United States v. Yashar","cite":"166 F.3d 873","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/166/873/","sum":"Construing the five-year statute of limitations in 18 U.S.C. 3282(a), which runs from the date on which the “offense shall have been committed”.","sumSrc":"brief:1","by":{"1":"26, 30, 47","2":"5"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"47"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(1)","(e)(2)(B)","(a)(2)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"1":"3, 21, 3, 22, passim, 3, 3"}},{"t":"usc","label":"21 U.S.C. § 849","url":"https://www.law.cornell.edu/uscode/text/21/849","subs":["(e)(1)(1982)"],"stext":{"head":"§849. Transportation safety offenses","paras":[[0,"(a) Definitions"],[0,"In this section—"],[1,"\"safety rest area\" means a roadside facility with parking facilities for the rest or other needs of motorists."],[1,"\"truck stop\" means a facility (including any parking lot appurtenant thereto) that—"],[2,"(A) has the capacity to provide fuel or service, or both, to any commercial motor vehicle (as defined in section 31301 of title 49), operating in commerce (as defined in that section); and"],[2,"(B) is located within 2,500 feet of the National System of Interstate and Defense Highways or the Federal-Aid Primary System."],[0,"(b) First offense"],[0,"A person who violates section 841(a)(1) of this title or section 856 of this title by distributing or possessing with intent to distribute a controlled substance in or on, or within 1,000 feet of, a truck stop or safety rest area is (except as provided in subsection (b)) 1 subject to—"],[1,"(1) twice the maximum punishment authorized by section 841(b) of this title; and"],[1,"(2) twice any term of supervised release authorized by section 841(b) of this title for a first offense."],[0,"(c) Subsequent offense"],[0,"A person who violates section 841(a)(1) of this title or section 856 of this title by distributing or possessing with intent to distribute a controlled substance in or on, or within 1,000 feet of, a truck stop or a safety rest area after a prior conviction or convictions under subsection (a) 2 have become final is subject to—"],[1,"(1) 3 times the maximum punishment authorized by section 841(b) of this title; and"],[1,"(2) 3 times any term of supervised release authorized by section 841(b) of this title for a first offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/849?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§849. Transportation safety offenses","tname":"Food and Drugs","by":{"1":"32"}},{"t":"law","label":"Firearms Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/459","by":{"1":"21"}},{"t":"usc","label":"18 U.S.C. § 3575","url":"https://www.law.cornell.edu/uscode/text/18/3575","subs":["(e)(1)(1982)","(1982)"],"op":1,"tname":"Crimes and Criminal Procedure","by":{"1":"32, 33, 32"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"1":"2, 3"}},{"t":"usc","label":"18 U.S.C. § 3282","url":"https://www.law.cornell.edu/uscode/text/18/3282","subs":["(a)"],"stext":{"head":"§3282. Offenses not capital","paras":[[0,"(a) In General.—Except as otherwise expressly provided by law, no person shall be prosecuted, tried, or punished for any offense, not capital, unless the indictment is found or the information is instituted within five years next after such offense shall have been committed."],[0,"(b) DNA Profile Indictment.—"],[1,"(1) In general.—In any indictment for an offense under chapter 109A for which the identity of the accused is unknown, it shall be sufficient to describe the accused as an individual whose name is unknown, but who has a particular DNA profile."],[1,"(2) Exception.—Any indictment described under paragraph (1), which is found not later than 5 years after the offense under chapter 109A is committed, shall not be subject to—"],[2,"(A) the limitations period described under subsection (a); and"],[2,"(B) the provisions of chapter 208 until the individual is arrested or served with a summons in connection with the charges contained in the indictment."],[1,"(3) Defined term.—For purposes of this subsection, the term \"DNA profile\" means a set of DNA identification characteristics."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3282?type=usc&year=mostrecent&link-type=html"},"head":"§3282. Offenses not capital","tname":"Crimes and Criminal Procedure","by":{"1":"15","2":"5"}},{"t":"usc","label":"18 U.S.C. § 3559","url":"https://www.law.cornell.edu/uscode/text/18/3559","subs":["(c)(1)"],"by":{"1":"33"}},{"t":"usc","label":"28 U.S.C. § 1915","url":"https://www.law.cornell.edu/uscode/text/28/1915","subs":["(g)"],"stext":{"head":"§1915. Proceedings in forma pauperis","paras":[[0,"(a)(1) Subject to subsection (b), any court of the United States may authorize the commencement, prosecution or defense of any suit, action or proceeding, civil or criminal, or appeal therein, without prepayment of fees or security therefor, by a person who submits an affidavit that includes a statement of all assets such prisoner possesses that the person is unable to pay such fees or give security therefor. Such affidavit shall state the nature of the action, defense or appeal and affiant's belief that the person is entitled to redress."],[0,"(2) A prisoner seeking to bring a civil action or appeal a judgment in a civil action or proceeding without prepayment of fees or security therefor, in addition to filing the affidavit filed under paragraph (1), shall submit a certified copy of the trust fund account statement (or institutional equivalent) for the prisoner for the 6-month period immediately preceding the filing of the complaint or notice of appeal, obtained from the appropriate official of each prison at which the prisoner is or was confined."],[0,"(3) An appeal may not be taken in forma pauperis if the trial court certifies in writing that it is not taken in good faith."],[0,"(b)(1) Notwithstanding subsection (a), if a prisoner brings a civil action or files an appeal in forma pauperis, the prisoner shall be required to pay the full amount of a filing fee. The court shall assess and, when funds exist, collect, as a partial payment of any court fees required by law, an initial partial filing fee of 20 percent of the greater of—"],[1,"(A) the average monthly deposits to the prisoner's account; or"],[1,"(B) the average monthly balance in the prisoner's account for the 6-month period immediately preceding the filing of the complaint or notice of appeal."],[0,"(2) After payment of the initial partial filing fee, the prisoner shall be required to make monthly payments of 20 percent of the preceding month's income credited to the prisoner's account. The agency having custody of the prisoner shall forward payments from the prisoner's account to the clerk of the court each time the amount in the account exceeds $10 until the filing fees are paid."],[0,"(3) In no event shall the filing fee collected exceed the amount of fees permitted by statute for the commencement of a civil action or an appeal of a civil action or criminal judgment."],[0,"(4) In no event shall a prisoner be prohibited from bringing a civil action or appealing a civil or criminal judgment for the reason that the prisoner has no assets and no means by which to pay the initial partial filing fee."],[0,"(c) Upon the filing of an affidavit in accordance with subsections (a) and (b) and the prepayment of any partial filing fee as may be required under subsection (b), the court may direct payment by the United States of the expenses of (1) printing the record on appeal in any civil or criminal case, if such printing is required by the appellate court; (2) preparing a transcript of proceedings before a United States magistrate judge in any civil or criminal case, if such transcript is required by the district court, in the case of proceedings conducted under section 636(b) of this title or under section 3401(b) of title 18, United States Code; and (3) printing the record on appeal if such printing is required by the appellate court, in the case of proceedings conducted pursuant to section 636(c) of this title. Such expenses shall be paid when authorized by the Director of the Administrative Office of the United States Courts."],[0,"(d) The officers of the court shall issue and serve all process, and perform all duties in such cases. Witnesses shall attend as in other cases, and the same remedies shall be available as are provided for by law in other cases."],[0,"(e)(1) The court may request an attorney to represent any person unable to afford counsel."],[0,"(2) Notwithstanding any filing fee, or any portion thereof, that may have been paid, the court shall dismiss the case at any time if the court determines that—"],[1,"(A) the allegation of poverty is untrue; or"],[1,"(B) the action or appeal—"],[2,"(i) is frivolous or malicious;"],[2,"(ii) fails to state a claim on which relief may be granted; or"],[2,"(iii) seeks monetary relief against a defendant who is immune from such relief."],[0,"(f)(1) Judgment may be rendered for costs at the conclusion of the suit or action as in other proceedings, but the United States shall not be liable for any of the costs thus incurred. If the United States has paid the cost of a stenographic transcript or printed record for the prevailing party, the same shall be taxed in favor of the United States."],[0,"(2)(A) If the judgment against a prisoner includes the payment of costs under this subsection, the prisoner shall be required to pay the full amount of the costs ordered."],[0,"(B) The prisoner shall be required to make payments for costs under this subsection in the same manner as is provided for filing fees under subsection (a)(2)."],[0,"(C) In no event shall the costs collected exceed the amount of the costs ordered by the court."],[0,"(g) In no event shall a prisoner bring a civil action or appeal a judgment in a civil action or proceeding under this section if the prisoner has, on 3 or more prior occasions, while incarcerated or detained in any facility, brought an action or appeal in a court of the United States that was dismissed on the grounds that it is frivolous, malicious, or fails to state a claim upon which relief may be granted, unless the prisoner is under imminent danger of serious physical injury."],[0,"(h) As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1915?type=usc&year=mostrecent&link-type=html"},"head":"§1915. Proceedings in forma pauperis","tname":"Judiciary and Judicial Procedure","by":{"1":"13, 14, 15","2":"8, 9"}},{"t":"case","label":"Brown v. United States","cite":"636 F.3d 674","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/636/674/","by":{"2":"20"}},{"t":"case","label":"People v. Alamo","cite":"315 N.E.2d 446","y":1974,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/315/446/","by":{"2":"11"}},{"t":"case","label":"People v. King","cite":"463 N.E.2d 601","y":1984,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/463/601/","by":{"2":"18"}},{"t":"case","label":"State v. Carlson","cite":"560 P.2d 26","y":1977,"court":"Alaska","url":"https://www.courtlistener.com/c/P.2d/560/26/","by":{"2":"12"}},{"t":"case","label":"(III) Cases—Continued United States v. Bryant","cite":"136 S. Ct. 1954","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1954/","sc":1,"by":{"2":"7"}},{"t":"case","label":"United States v. Dudley, --- F.4th ----","cite":"2021 WL 3086186","y":2021,"court":"11th Cir. July 22","op":1,"by":{"2":"19"}},{"t":"case","label":"United States v. Hill","cite":"440 F.3d 292","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/440/292/","by":{"2":"15"}},{"t":"case","label":"United States v. Riddle","cite":"47 F.3d 460","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/47/460/","op":1,"by":{"2":"20"}},{"t":"case","label":"United States v. Rideout","cite":"3 F.3d 32","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/3/32/","op":1,"by":{"2":"21"}},{"t":"case","label":"United States v. Stearns","cite":"387 F.3d 104","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/387/104/","op":1,"by":{"2":"20, 21"}},{"t":"case","label":"United States v. Thomas","cite":"211 F.3d 316","y":2000,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/211/316/","by":{"2":"14"}},{"t":"case","label":"United States v. Wilson","cite":"27 F.3d 1126","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/27/1126/","by":{"2":"14"}},{"t":"usc","label":"16 U.S.C. § 2621","url":"https://www.law.cornell.edu/uscode/text/16/2621","subs":["(d)(3)"],"by":{"2":"7"}},{"t":"usc","label":"19 U.S.C. § 1431a","url":"https://www.law.cornell.edu/uscode/text/19/1431a","subs":["(d)(4)"],"by":{"2":"7"}},{"t":"usc","label":"42 U.S.C. § 4121","url":"https://www.law.cornell.edu/uscode/text/42/4121","subs":["(a)(7)"],"by":{"2":"5"}}]};